  photoOf: `Photo from {t} ({i} of {n}). `, kept24: `Your photo is kept for 24 hours and then deleted.`,
  qrFail: `The QR code could not be made (no internet?). Link: {url}`, noRecent: `There are no recent photos with a QR code.`,
