  cr_moon: `Photo : NASA, Apollo 11 (1969).`, cr_pillars: `Photo : NASA, ESA et l'équipe Hubble Heritage (2014).`,
  'cr_deep-field': `Photo : NASA et ESA, Hubble Ultra Deep Field (2004).`,
